#pragma once
#include "Sequencer.h"
namespace noctrl {
inline float sequenceCurveValue(const std::vector<SeqPoint>& curve,double time){if(curve.empty())return 0;auto next=std::upper_bound(curve.begin(),curve.end(),time,[](double t,auto point){return t<point.time;});if(next==curve.begin())return next->value;if(next==curve.end())return curve.back().value;auto& a=*(next-1);double t=juce::jlimit(0.,1.,(time-a.time)/juce::jmax(.000001,next->time-a.time));t=std::pow(t,std::pow(4.,(double)a.curve));return a.value+(next->value-a.value)*(float)t;}
inline SeqNote sliceSequenceNote(SeqNote n,double begin,double end){double oldStart=n.start,oldLength=n.length;auto curve=n.pitchCurve;n.start=juce::jmax(n.start,begin);n.length=juce::jmax(.0001,juce::jmin(oldStart+oldLength,end)-n.start);if(!curve.empty()){n.pitchCurve.clear();for(int i=0;i<=16;++i)n.pitchCurve.push_back({i/16.,sequenceCurveValue(curve,(n.start-oldStart+n.length*i/16)/oldLength)});}return n;}
inline void eraseSequenceRange(SeqSlot& slot,double begin,double end){std::vector<SeqNote> next;for(auto n:slot.notes){if(n.start>=end||n.start+n.length<=begin)next.push_back(n);else {if(n.start<begin)next.push_back(sliceSequenceNote(n,n.start,begin));if(n.start+n.length>end)next.push_back(sliceSequenceNote(n,end,n.start+n.length));}}slot.notes=std::move(next);for(auto& lane:slot.lanes)lane.points.erase(std::remove_if(lane.points.begin(),lane.points.end(),[&](auto pt){return pt.time>=begin&&pt.time<end;}),lane.points.end());}
inline int sequenceScaleNote(int note,int key,int scale){if(key==0||scale==4)return juce::jlimit(0,127,note);const int masks[]={0xAB5,0x5AD,0x295,0x6AD};for(int d=0;d<12;++d)for(int sign:{-1,1}){int value=note+d*sign;if(value>=0&&value<128&&(masks[juce::jlimit(0,3,scale)]&(1<<((value-key+1+120)%12))))return value;}return juce::jlimit(0,127,note);}
inline double editSequenceNotes(SeqSlot& slot,const std::vector<int>& selection,const juce::String& operation,double grid,int key,int scale){
 std::vector<int> indices;for(int i:selection)if(i>=0&&i<(int)slot.notes.size())indices.push_back(i);if(indices.empty())return 0;double begin=256,end=0;for(int i:indices){begin=juce::jmin(begin,slot.notes[i].start);end=juce::jmax(end,slot.notes[i].start+slot.notes[i].length);}double needed=0;
 if(operation=="Duplicate"){auto original=slot.notes;for(int i:indices)if(slot.notes.size()<512){auto n=original[i];n.start+=end-begin;needed=juce::jmax(needed,n.start+n.length);slot.notes.push_back(n);}return needed;}
 if(operation=="Legato"){std::stable_sort(indices.begin(),indices.end(),[&](int a,int b){return slot.notes[a].start<slot.notes[b].start;});for(int i:indices){double next=256;for(int j:indices)if(slot.notes[j].start>slot.notes[i].start+.00001)next=juce::jmin(next,slot.notes[j].start);if(next<256)slot.notes[i].length=next-slot.notes[i].start;}return end;}
 if(operation=="Chop"){auto original=slot.notes;for(int i:indices){auto n=original[i];int count=juce::jmin(64,juce::jmax(2,(int)std::ceil(n.length/grid)));double size=n.length/count;slot.notes[i]=sliceSequenceNote(n,n.start,n.start+size);for(int k=1;k<count&&slot.notes.size()<512;++k)slot.notes.push_back(sliceSequenceNote(n,n.start+k*size,n.start+(k+1)*size));}return end;}
 bool mute=false;for(int i:indices)mute|=!slot.notes[i].muted;
 for(int i:indices){auto& n=slot.notes[i];if(operation=="Mute")n.muted=mute;else if(operation=="Quantize")n.start=juce::jlimit(0.,256.,std::round(n.start/grid)*grid);else if(operation=="Conform to Scale")n.pitch=sequenceScaleNote(n.pitch,key,scale);else if(operation=="Reverse")n.start=begin+end-n.start-n.length;else if(operation=="Time 50%"||operation=="Time 200%"){double factor=operation=="Time 50%"?.5:2;n.start=begin+(n.start-begin)*factor;n.length*=factor;}needed=juce::jmax(needed,n.start+n.length);}return needed;
}
}
